<template>
  <div class="send" v-show="show"><div class="write-box"><div class="title"><div class="title-left"><span class="title-text"><Icon icon="hugeicons:quill-write-01" width="28" height="28"/></span><span class="sender">{{ $t('sender') }}:</span><span class="sender-name">{{ form.name }}</span><span class="send-email"><{{ form.sendEmail }}></span></div><div @click="close" style="cursor:pointer"><Icon icon="material-symbols-light:close-rounded" width="22" height="22"/></div></div><div class="container"><div class="recipient-row"><el-input-tag @add-tag="addTagChange" tag-type="primary" @input="inputChange" size="default" v-model="form.receiveEmail"><template #prefix><div class="item-title">{{ $t('recipient') }}</div><el-select ref="mySelect" class="write-select" popper-class="write-select" :show-arrow="false" :no-match-text="' '" :no-data-text="' '" @visible-change="selectStatusChange" @change="selectChange"><el-option v-for="item in selectRecipientList" :key="item" :label="item" :value="item"/></el-select></template><template #suffix><Icon icon="fa7-solid:user-plus" width="20" height="20" @click.stop="openContactsFor('to')"/></template></el-input-tag><div class="cc-bcc-links"><span @click="showCc=true">CC</span><span @click="showBcc=true">BCC</span></div></div><el-input-tag v-if="showCc" @add-tag="addCcTag" tag-type="primary" v-model="form.cc" placeholder="CC"><template #prefix><div class="item-title">CC</div></template><template #suffix><Icon icon="fa7-solid:user-plus" width="20" height="20" @click.stop="openContactsFor('cc')"/></template></el-input-tag><el-input-tag v-if="showBcc" @add-tag="addBccTag" tag-type="primary" v-model="form.bcc" placeholder="BCC"><template #prefix><div class="item-title">BCC</div></template><template #suffix><Icon icon="fa7-solid:user-plus" width="20" height="20" @click.stop="openContactsFor('bcc')"/></template></el-input-tag><el-input v-model="form.subject" :placeholder="t('subject')"/><tinyEditor :def-value="defValue" ref="editor" @change="change" @focus="focusChange"/><div class="button-item"><div class="att-add" @click="chooseFile"><Icon icon="iconamoon:attachment-fill" width="24" height="24"/></div><div class="att-list"><div class="att-item" v-for="(item,index) in form.attachments" :key="index"><Icon v-bind="getIconByName(item.filename)"/><span class="att-filename">{{item.filename}}</span><span class="att-size">{{formatBytes(item.size)}}</span><Icon icon="material-symbols-light:close-rounded" @click="delAtt(index)" width="22" height="22"/></div></div><el-button type="primary" @click="sendEmail">{{form.sendType==='reply'?$t('reply'):form.sendType==='forward'?$t('forward'):$t('send')}}</el-button></div></div></div><el-dialog top="10vh" v-model="showContacts" @closed="clearSelectContact" :title="t('recentContacts')"><el-table ref="contactsTabRef" row-key="email" :data="contacts" style="height:445px"><el-table-column type="selection" width="32"/><el-table-column property="email" :label="t('emailAccount')"/><el-table-column width="55"><template #default><Icon icon="mage:user" width="22" height="22"/></template></el-table-column></el-table><div class="contacts-bottom"><el-button @click="deleteContact">{{t('clear')}}</el-button><el-button type="primary" @click="chooseContact">{{t('selectContacts')}}</el-button></div></el-dialog></div>
</template>
<script setup>
import tinyEditor from '@/components/tiny-editor/index.vue';import {h,nextTick,onMounted,onUnmounted,reactive,ref,computed} from 'vue';import {Icon} from '@iconify/vue';import {useUserStore} from '@/store/user.js';import {emailSend} from '@/request/email.js';import {isEmail} from '@/utils/verify-utils.js';import {useAccountStore} from '@/store/account.js';import {useEmailStore} from '@/store/email.js';import {fileToBase64,formatBytes} from '@/utils/file-utils.js';import {getIconByName} from '@/utils/icon-utils.js';import sendPercent from '@/components/send-percent/index.vue';import {toOssDomain} from '@/utils/convert.js';import {formatDetailDate} from '@/utils/day.js';import {useSettingStore} from '@/store/setting.js';import {userDraftStore} from '@/store/draft.js';import {useWriterStore} from '@/store/writer.js';import {useI18n} from 'vue-i18n';import {ElMessageBox,ElMessage,ElNotification} from 'element-plus';
defineExpose({open,openReply,openReplyAll,openForward,openDraft});const {t}=useI18n();const writerStore=useWriterStore(),draftStore=userDraftStore(),settingStore=useSettingStore(),emailStore=useEmailStore(),accountStore=useAccountStore(),userStore=useUserStore();const editor=ref({}),show=ref(false),percent=ref(0),percentMessage=ref(null),sending=ref(false),defValue=ref(''),contactsTabRef=ref({}),showContacts=ref(false),contactTarget=ref('to'),mySelect=ref(),selectStatus=ref(false),showCc=ref(false),showBcc=ref(false);const form=reactive({sendEmail:'',receiveEmail:[],cc:[],bcc:[],accountId:-1,name:'',subject:'',content:'',sendType:'',text:'',emailId:0,attachments:[],draftId:null});const selectRecipientList=ref([]);const contacts=computed(()=>writerStore.sendRecipientRecord.map(email=>({email})));
function openContactsFor(target){contactTarget.value=target;showContacts.value=true;nextTick(()=>{(form[target]||[]).forEach(email=>{if(writerStore.sendRecipientRecord.includes(email))contactsTabRef.value.toggleRowSelection({email})})})}function chooseContact(){const selected=contactsTabRef.value.getSelectionRows().map(x=>x.email);selected.forEach(email=>{if(!form[contactTarget.value].includes(email))form[contactTarget.value].push(email)});showContacts.value=false}function deleteContact(){ElMessageBox.confirm(t('confirmDeletionOfContacts'),{confirmButtonText:t('confirm'),cancelButtonText:t('cancel'),type:'warning'}).then(()=>{const selected=contactsTabRef.value.getSelectionRows().map(x=>x.email);form[contactTarget.value]=form[contactTarget.value].filter(x=>!selected.includes(x));if(contactTarget.value==='to')writerStore.sendRecipientRecord=writerStore.sendRecipientRecord.filter(x=>!selected.includes(x))})}function clearSelectContact(){contactsTabRef.value.clearSelection()}
function inputChange(value){selectRecipientList.value=writerStore.sendRecipientRecord.filter(x=>value&&!form.receiveEmail.includes(x)&&x.startsWith(value)).slice(0,10);if(selectRecipientList.value.length&&!selectStatus.value)openSelect();if(!selectRecipientList.value.length&&selectStatus.value)openSelect()}function selectChange(value){form.receiveEmail.push(value)}function selectStatusChange(v){selectStatus.value=v}function openSelect(){mySelect.value?.toggleMenu()}function addTagChange(val){form.receiveEmail.splice(form.receiveEmail.length-1,1);String(val).split(/[,，]/).map(x=>x.trim().toLowerCase()).filter(x=>isEmail(x)).forEach(x=>{if(!form.receiveEmail.includes(x))form.receiveEmail.push(x)})}function addCcTag(val){addTags(val,'cc')}function addBccTag(val){addTags(val,'bcc')}function addTags(val,key){form[key]=Array.from(new Set([...form[key],...String(val).split(/[,，]/).map(x=>x.trim().toLowerCase()).filter(x=>isEmail(x))]))}
function resetForm(){form.receiveEmail=[];form.cc=[];form.bcc=[];form.subject='';form.content='';form.sendType='';form.emailId=0;form.attachments=[];form.draftId=null;showCc=false;showBcc=false;editor.value?.clearEditor?.()}function change(content,text){form.content=content;form.text=text}function focusChange(){if(selectStatus.value)openSelect()}function formatImage(content){return String(content||'').replace(/{{domain}}/g,toOssDomain(settingStore.settings.r2Domain)+'/')}
function quote(email,reply){const body=formatImage(email.content)||`<pre style="font-family:inherit;white-space:pre-wrap;margin:0">${email.text||''}</pre>`;const header=reply?`${formatDetailDate(email.createTime)} ${email.name||''} &lt;${email.sendEmail||''}&gt; ${t('wrote')}`:`Forwarded message: ${email.name||''} &lt;${email.sendEmail||''}&gt;`;return `<div></div><div style="margin-top:16px;padding-top:10px;border-top:1px solid #dcdfe6;color:#606266">${header}</div><blockquote class="mceNonEditable" style="margin:8px 0 0 .8ex;border-left:2px solid #c0c4cc;padding-left:1ex">${body}</blockquote>`}
function setEditorContent(html){nextTick(()=>{try{editor.value?.setContent?.(html)}catch(e){console.warn('set reply/forward content failed',e)}})}
function openReply(email){resetForm();form.receiveEmail.push(String(email.sendEmail||'').trim().toLowerCase());form.subject=/^(Re:|Re：|回复：|回复:)/i.test(email.subject||'')?email.subject:'Re: '+(email.subject||'');form.sendType='reply';form.emailId=email.emailId;defValue.value=quote(email,true);open();setEditorContent(defValue.value)}
function openReplyAll(email){resetForm();form.receiveEmail.push(String(email.sendEmail||'').trim().toLowerCase());let me=String(accountStore.currentAccount?.email||userStore.user?.email||'').toLowerCase(),to=[],cc=[];try{to=JSON.parse(email.recipient||'[]').map(x=>String(x.address||x).trim().toLowerCase())}catch{}try{cc=JSON.parse(email.cc||'[]').map(x=>String(x.address||x).trim().toLowerCase())}catch{}form.cc=Array.from(new Set([...to,...cc])).filter(x=>x&&x!==me&&!form.receiveEmail.includes(x));form.subject=/^(Re:|Re：|回复：|回复:)/i.test(email.subject||'')?email.subject:'Re: '+(email.subject||'');form.sendType='reply';form.emailId=email.emailId;showCc=form.cc.length>0;defValue.value=quote(email,true);open();setEditorContent(defValue.value)}
function openForward(email){resetForm();form.subject=/^(Fw:|Fwd:|转发：|转发:)/i.test(email.subject||'')?email.subject:'Fwd: '+(email.subject||'');form.sendType='forward';defValue.value=quote(email,false);open();setEditorContent(defValue.value);if(Array.isArray(email.attachments)&&email.attachments.length){form.attachments.push(...email.attachments.map(att=>({content:att.content,filename:att.filename,size:att.size,contentType:att.contentType||att.mimeType||att.type||'application/octet-stream'})))} }
function open(){if(!accountStore.currentAccount.email){form.sendEmail=userStore.user.email;form.accountId=userStore.user.account.accountId;form.name=userStore.user.name}else{form.sendEmail=accountStore.currentAccount.email;form.accountId=accountStore.currentAccount.accountId;form.name=accountStore.currentAccount.name}show.value=true;nextTick(()=>editor.value?.focus?.())}function openDraft(draft){Object.assign(form,{...draft});show.value=true;defValue.value=form.content;setEditorContent(form.content)}
function delAtt(i){form.attachments.splice(i,1)}function chooseFile(){const input=document.createElement('input');input.type='file';input.multiple=true;input.click();input.onchange=async e=>{for(const f of e.target.files)form.attachments.push({content:await fileToBase64(f),filename:f.name,size:f.size,contentType:f.type})}}
async function sendEmail(){if(!form.receiveEmail.length)return ElMessage.error(t('emptyRecipientMsg'));if(!form.subject)return ElMessage.error(t('emptySubjectMsg'));if(!form.content)form.content=editor.value.getContent();if(!form.content)return ElMessage.error(t('emptyContentMsg'));if(sending.value)return ElMessage.error(t('sendingErrorMsg'));percentMessage.value=ElMessage({message:()=>h(sendPercent,{value:percent.value,desc:t('sending')}),duration:0});sending.value=true;show.value=false;emailSend(form,e=>percent.value=Math.round((e.loaded*98)/e.total)).then(list=>{list.forEach(x=>emailStore.sendScroll?.addItem(x));ElNotification({title:t('sendSuccessMsg'),type:'success',message:h('span',{style:'color:teal'},list[0].subject),position:'bottom-right'});addRecipientRecord();resetForm()}).catch(e=>{ElNotification({title:t('sendFailMsg'),type:'error',message:e.message});show.value=true}).finally(()=>{percentMessage.value?.close();percent.value=0;sending.value=false})}
function addRecipientRecord(){const all=[...form.receiveEmail,...form.cc,...form.bcc];writerStore.sendRecipientRecord=writerStore.sendRecipientRecord.filter(x=>!all.includes(x));writerStore.sendRecipientRecord.unshift(...all);writerStore.sendRecipientRecord=writerStore.sendRecipientRecord.slice(0,500)}function close(){show.value=false;resetForm()}const handleKeyDown=e=>{if(e.key==='Escape')close()};onMounted(()=>window.addEventListener('keydown',handleKeyDown));onUnmounted(()=>window.removeEventListener('keydown',handleKeyDown));
</script>
<style scoped>.recipient-row{display:flex;align-items:center;gap:8px}.recipient-row>.el-input-tag{flex:1}.cc-bcc-links{display:flex;gap:8px;font-size:13px;color:var(--el-color-primary);cursor:pointer}.container>.el-input-tag{margin-top:6px}</style>
